<?php require_once 'includes.php';require_login();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$from=trim((string)($_POST['from_city']??''));$to=trim((string)($_POST['to_place']??''));$date=(string)($_POST['travel_date']??'');$seats=filter_var($_POST['seats']??2,FILTER_VALIDATE_INT);$cost=filter_var($_POST['estimated_cost']??0,FILTER_VALIDATE_FLOAT);$days=filter_var($_POST['duration_days']??1,FILTER_VALIDATE_INT);$style=(string)($_POST['travel_style']??'other');$type=(string)($_POST['trip_type']??'group');$desc=trim((string)($_POST['description']??''));$vehicle=trim((string)($_POST['vehicle']??''));$luggage=trim((string)($_POST['luggage_notes']??''));if($title===''||strlen($title)>150)$errors[]='Enter a trip title (max 150 characters).';if($from===''||$to==='')$errors[]='Enter the starting point and destination.';$dt=DateTime::createFromFormat('Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date<date('Y-m-d'))$errors[]='Choose today or a future date.';if(!$seats||$seats<1||$seats>8)$errors[]='Seats must be 1–8.';if($cost===false||$cost<0)$errors[]='Enter a valid cost.';if(!$days||$days<1||$days>60)$errors[]='Duration must be 1–60 days.';if(!in_array($style,['beach','nature','culture','city','other'],true))$style='other';if(!in_array($type,['group','carpool'],true))$type='group';if($type==='carpool'&&$vehicle==='')$errors[]='Add vehicle details for a carpool listing.';if(!$errors){$s=db()->prepare('INSERT INTO trips(host_id,title,from_city,to_place,travel_date,seats_total,seats_available,estimated_cost,duration_days,travel_style,trip_type,description,vehicle,luggage_notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$_SESSION['user_id'],$title,$from,$to,$date,$seats,$seats,$cost,$days,$style,$type,$desc?:null,$vehicle?:null,$luggage?:null]);$_SESSION['flash']='Your trip has been published.';header('Location: '.($type==='carpool'?'rides.php':'group-trips.php'));exit;}}page_header('Create a trip');?><section class="form-layout"><div class="form-panel"><p class="eyebrow">YOUR PLAN, YOUR PEOPLE</p><h1>Create a trip</h1><p>Share a group trip or offer empty seats in your car.</p><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><label class="form-field full">Trip title<input name="title" required maxlength="150" value="<?=e($_POST['title']??'')?>" placeholder="Weekend in Goa"></label><label class="form-field">From<input name="from_city" required value="<?=e($_POST['from_city']??'')?>" placeholder="Hyderabad"></label><label class="form-field">To<input name="to_place" required value="<?=e($_POST['to_place']??'')?>" placeholder="Goa"></label><label class="form-field">Date<input name="travel_date" type="date" data-min-today required value="<?=e($_POST['travel_date']??'')?>"></label><label class="form-field">Trip type<select name="trip_type"><option value="group">Group trip</option><option value="carpool" <?=($_POST['trip_type']??'')==='carpool'?'selected':''?>>Car seat sharing</option></select></label><label class="form-field">Available seats<select name="seats"><?php for($i=1;$i<=8;$i++):?><option value="<?=$i?>" <?=((int)($_POST['seats']??2)===$i)?'selected':''?>><?=$i?></option><?php endfor;?></select></label><label class="form-field">Contribution per person (₹)<input name="estimated_cost" type="number" min="0" step="50" required value="<?=e((string)($_POST['estimated_cost']??0))?>"></label><label class="form-field">Duration in days<input name="duration_days" type="number" min="1" max="60" value="<?=e((string)($_POST['duration_days']??1))?>"></label><label class="form-field">Style<select name="travel_style"><option value="other">Other</option><option value="beach">Beach</option><option value="nature">Nature & hills</option><option value="culture">Culture & heritage</option><option value="city">City</option></select></label><label class="form-field full">Vehicle details (carpool only)<input name="vehicle" maxlength="120" value="<?=e($_POST['vehicle']??'')?>" placeholder="Car type and passenger seats"></label><label class="form-field full">Luggage information<textarea name="luggage_notes" maxlength="255"><?=e($_POST['luggage_notes']??'')?></textarea></label><label class="form-field full">Description<textarea name="description" maxlength="4000" placeholder="Itinerary, public meeting point, cost split and expectations"><?=e($_POST['description']??'')?></textarea></label></div><div class="safety-note">Use public meeting points. Confirm identity, vehicle, route and cost-sharing details before travelling.</div><br><button class="btn btn-primary full-width">Publish trip</button></form></div></section><?php page_footer();?>